 products(limit: 500,offset : offsetValue, where: $productFilter) {
 count
 total
 results {
 id
 key
 masterData {
 published
 current {
 nameAllLocales {
 locale
 value
 }
 masterVariant {
 attributesRaw(includeNames: [ requestedAttributes ]) {
 name
 value

 }
 }
 }
 }
 }
 }
